. 실제 입고 출처는 미확인으로 남기며 현재층과 분리해 금액만 기록."},{"id":"4970","line":4,"snapshot":"9ee8f091b11d1155d77796eb3d4cc00b","cost_snapshot":"c23bda93a31aa2f20e82973ab23c5d16","kind":"untracked_manual","note":"재고 미관리 품목. 사용자가 확정한 금액만 원장에 기록하며 재고·원가층은 생성하거나 차감하지 않음."},{"id":"4961","line":6,"snapshot":"24e19622c5b8c3d2c2148b346f0426f1","cost_snapshot":"befb6dcf768623565753f8842a92fe4a","kind":"historical_manual","note":"7월 22일 기초 원가 이전의 누락 서비스. 사용자 입력 단가로 금액 확정. 실제 입고 출처는 미확인으로 남기며 현재층과 분리해 금액만 기록."},{"id":"4593","line":6,"snapshot":"c4d40690b5f6abe1d0ec0117adbf1417","cost_snapshot":"63337ced3e42c6bf035c14706cb782d2","kind":"historical_manual","note":"7월 22일 기초 원가 이전의 누락 서비스. 사용자 입력 단가로 금액 확정. 실제 입고 출처는 미확인으로 남기며 현재층과 분리해 금액만 기록."}]'::jsonb; p jsonb; ctx jsonb; oldctx jsonb; newctx jsonb; before_state jsonb; after_state jsonb; report jsonb; before_cost bigint; after_cost bigint;
begin
perform set_config('request.jwt.claim.sub',(select id::text from users where oss_role='master' order by created_at limit 1),true);
lock table logs in share row exclusive mode;
perform lock_inventory_cost_review();
lock table inventory_service_cost_links,inventory_service_manual_costs,inventory_service_cost_reviews in share row exclusive mode;
before_state:=jsonb_build_object('stock',(select md5(jsonb_agg(to_jsonb(b) order by item_name)::text) from inventory_balances b),'layers',(select md5(jsonb_agg(to_jsonb(l) order by id)::text) from inventory_cost_layers l),'events',(select md5(jsonb_agg(to_jsonb(e) order by id)::text) from inventory_cost_events e),'allocations',(select md5(jsonb_agg(to_jsonb(a) order by id)::text) from inventory_cost_allocations a),'links',(select md5(jsonb_agg(to_jsonb(s) order by log_id,line_index,allocation_id)::text) from inventory_service_cost_links s),'manual',(select md5(jsonb_agg(to_jsonb(m) order by log_id,line_index)::text) from inventory_service_manual_costs m));
select sum(total_cost::bigint) into before_cost from inventory_cost_reporting_events where direction='out';
if (select count(*) from inventory_service_manual_costs)<>21 or exists(select 1 from inventory_service_cost_reviews) then raise exception '입력 또는 대사 상태 변경'; end if;
for p in select value from jsonb_array_elements(plans) loop
ctx:=get_service_cost_entry_unreviewed((p->>'id')::bigint,(p->>'line')::integer);
if ctx->>'snapshot' is distinct from p->>'snapshot' or md5(inventory_cost_review_snapshot(ctx->>'item_name')::text) is distinct from p->>'cost_snapshot' then raise exception '원본 변경: %',p->>'id'; end if;
if ctx->'manual'='null'::jsonb or (ctx->>'has_allocation')::boolean or ctx->>'linked_cost' is not null then raise exception '기존 배정 중복 또는 입력 누락'; end if;
if p->>'kind'='historical_manual' and (ctx->>'event_at')::timestamptz>='2026-07-22 00:00+09' then raise exception '과거 기준 밖'; end if;
if p->>'kind'='untracked_manual' and is_inventory_item_tracked(ctx->>'item_name') then raise exception '추적 설정 변경'; end if;
end loop;
for p in select value from jsonb_array_elements(plans) loop
oldctx:=get_service_cost_entry((p->>'id')::bigint,(p->>'line')::integer);
insert into inventory_service_cost_reviews(log_id,line_index,kind,note,reviewed_input,cost_snapshot,reviewed_by)
values((p->>'id')::bigint,(p->>'line')::integer,p->>'kind',p->>'note',oldctx-'history',p->>'cost_snapshot',auth.uid());
newctx:=get_service_cost_entry((p->>'id')::bigint,(p->>'line')::integer);
insert into inventory_service_manual_cost_audit(log_id,line_index,before_cost,after_cost,note,created_by)
values((p->>'id')::bigint,(p->>'line')::integer,oldctx-'history',newctx-'history','원가 대사: '||(p->>'note'),auth.uid());
end loop;
after_state:=jsonb_build_object('stock',(select md5(jsonb_agg(to_jsonb(b) order by item_name)::text) from inventory_balances b),'layers',(select md5(jsonb_agg(to_jsonb(l) order by id)::text) from inventory_cost_layers l),'events',(select md5(jsonb_agg(to_jsonb(e) order by id)::text) from inventory_cost_events e),'allocations',(select md5(jsonb_agg(to_jsonb(a) order by id)::text) from inventory_cost_allocations a),'links',(select md5(jsonb_agg(to_jsonb(s) order by log_id,line_index,allocation_id)::text) from inventory_service_cost_links s),'manual',(select md5(jsonb_agg(to_jsonb(m) order by log_id,line_index)::text) from inventory_service_manual_costs m));
if before_state is distinct from after_state then raise exception '재고/FIFO/입력 원본 변경. 전체 취소'; end if;
select sum(total_cost::bigint) into after_cost from inventory_cost_reporting_events where direction='out';
if after_cost-before_cost<>8400 or (select count(*) from inventory_cost_reporting_events where reference_type='manual_service_cost')<>15 then raise exception '원장 반영 금액 또는 건수 오류'; end if;
if (select count(*) from inventory_service_cost_reviews where kind='offset_review')<>6 then raise exception '상쇄 보류 건수 오류'; end if;
if (select sum(m.unit_cost::bigint*(l.jsonb->'items'->(m.line_index-1)->>'quantity')::integer) from inventory_service_cost_reviews r join inventory_service_manual_costs m using(log_id,line_index) join logs l on l.id=m.log_id where r.kind='offset_review')<>15000 then raise exception '상쇄 보류 금액 오류'; end if;
report:=get_inventory_cost_integrity_report(1000);
if (report->>'stockMismatchCount')::integer<>0 or (report->>'layerMismatchCount')::integer<>0 or (report->>'outboundMismatchCount')::integer<>0 then raise exception '무결성 검증 실패'; end if;
end $review$;
with actor as materialized(select set_config('request.jwt.claim.sub',(select id::text from users where oss_role='master' order by created_at limit 1),true))
select get_inventory_cost_integrity_report(1000)-'missingServiceLines' integrity,
(select count(*) from inventory_cost_reporting_events where reference_type='manual_service_cost') posted_count,
(select sum(total_cost) from inventory_cost_reporting_events where reference_type='manual_service_cost') posted_cost,
(select jsonb_agg(t) from (select r.kind,count(*) count,sum(m.unit_cost::bigint*(l.jsonb->'items'->(m.line_index-1)->>'quantity')::integer) cost from inventory_service_cost_reviews r join inventory_service_manual_costs m using(log_id,line_index) join logs l on l.id=m.log_id group by r.kind) t) review_totals from actor;
commit;
